#!/usr/bin/env bash
# SPDX-FileCopyrightText: Cadasto B.V.
# SPDX-License-Identifier: BUSL-1.1
# Render the class partials of the draft openEHR specification modules
# under docs/specifications/*/antora/ FROM their BMM schemas.
#
# In openEHR/specifications-RM the class partials are generated by
# bmm-publisher from the BMM. This script writes the same three partials
# per class in the same table and JSON form, so a draft's pages never carry
# a hand-written class table:
#
#   modules/ROOT/partials/definitions/<class>.adoc  the Definition table
#   modules/ROOT/partials/BMMs/<class>.adoc         the class as BMM JSON
#   modules/ROOT/partials/classes/<class>.adoc      the tabs that include both
#
# The Effective and UML tabs and the class diagrams come from bmm-publisher
# when a module enters the RM repository, and replace these partials.
#
# A type links to its definition: a class of the draft package to its
# module's package page, an RM class to the page of its RM package, and a
# BASE class or primitive type to the `{class_<name>}` attribute the RM
# component defines.
#
# Usage:
#   scripts/render/bmm-partials.sh           write every draft's partials
#   scripts/render/bmm-partials.sh --check   fail when a committed partial
#                                            differs from its rendering
set -euo pipefail

root="$(cd "$(dirname "$0")/../.." && pwd)"
cd "$root"

rm_bmm=docs/specs/openehr/RM/computable/BMM/openehr_rm_1.2.0.bmm.json
base_bmm=docs/specs/openehr/BASE/computable/BMM/openehr_base_1.3.0.bmm.json

# One row per draft: the BMM, the Antora module, the antora tree.
drafts=(
  "tools/openehr-codegen/draft/bmm/openehr_access_log_0.1.0.bmm.json access_log docs/specifications/access-log/antora"
  "tools/openehr-codegen/draft/bmm/openehr_access_control_0.1.0.bmm.json access_control docs/specifications/access-control/antora"
)

mode="write"
case "${1:-}" in
  "") ;;
  --check) mode=check ;;
  *)
    echo "usage: $0 [--check]" >&2
    exit 2
    ;;
esac

# The page of each RM class: `<module>:<package>_package.adoc`, where the
# module is the top RM package and the page the innermost package that
# holds the class (`date_time` sits inside `quantity` in the RM BMM).
rm_pages="$(jq -c '
  def walk_sub($module):
    ((.classes // [])[] as $c | {key: $c, value: "\($module):\(.name)_package.adoc"}),
    ((.packages // {})[] | walk_sub($module));
  def walk_pkg($module):
    ((.classes // [])[] | {key: ., value: "\($module):\($module)_package.adoc"}),
    ((.packages // {})[] | walk_sub($module));
  [.packages[]
   | (.name | sub("^org\\.openehr\\.rm\\."; "")) as $module
   | walk_pkg($module)
  ] | from_entries' "$rm_bmm")"
base_types="$(jq -c '[(.class_definitions // {}), (.primitive_types // {}) | keys[]]' "$base_bmm")"

# shellcheck disable=SC2016 # the jq program is single-quoted on purpose
render_program='
def lower: ascii_downcase;
def page_of($module): "\($module):\($module)_package.adoc";
def xref($t):
  if $own | index($t) then
    "xref:\($module | page_of(.))#_\($t | lower)_class[\($t)]"
  elif $rm[$t] then
    "xref:\($rm[$t])#_\($t | lower)_class[\($t)]"
  elif $base | index($t) then
    "xref:{class_\($t | lower)}[\($t)]"
  else
    error("type resolved nowhere: \($t)")
  end;
def type_of:
  if ._type == "P_BMM_CONTAINER_PROPERTY" then
    "\(xref(.type_def.container_type))<\(xref(.type_def.type))>"
  elif ._type == "P_BMM_GENERIC_PROPERTY" then
    "\(xref(.type_def.root_type))<\(.type_def.generic_parameters | map(xref(.)) | join(","))>"
  elif ._type == "P_BMM_SIMPLE_TYPE" or ._type == "P_BMM_SINGLE_PROPERTY" then
    xref(.type)
  else
    error("unsupported BMM form: \(._type)")
  end;
def existence: if .is_mandatory then "1..1" else "0..1" end;
def definition:
  [
    "[cols=\"^1,3,5\"]",
    "|===",
    "h|*Class*",
    "2+^h|*\(.name)\(if .is_abstract then " (abstract)" else "" end)*",
    "",
    "h|*Description*",
    "2+a|\(.documentation)",
    "",
    (if .ancestors then
      "h|*Inherit*",
      "2+|\(.ancestors | map("`\(xref(.))`") | join(", "))",
      ""
    else empty end),
    (if .properties then
      "h|*Attributes*", "^h|*Signature*", "^h|*Meaning*", "",
      (.properties[] |
        "h|*\(existence)*",
        "|*\(.name)*: `\(type_of)`",
        "a|\(.documentation)",
        "")
    else empty end),
    (if .functions then
      "h|*Functions*", "^h|*Signature*", "^h|*Meaning*", "",
      (.functions[] |
        "h|*1..1*",
        "|*\(.name)* (): `\(.result | type_of)`",
        "a|\(.documentation)",
        "")
    else empty end),
    (if .invariants then
      (.invariants | to_entries | to_entries[] |
        (if .key == 0 then "h|*Invariants*" else "h|" end),
        "2+a|__\(.value.key)__: `\(.value.value)`",
        "")
    else empty end),
    "|==="
  ] | join("\n");
.class_definitions[$class] | definition
'

tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT

stale=0
for row in "${drafts[@]}"; do
  read -r bmm module tree <<<"$row"
  partials="$tree/modules/ROOT/partials"
  own="$(jq -c '[.class_definitions | keys[]]' "$bmm")"
  for class in $(jq -r '.packages[].classes[]' "$bmm"); do
    name="$(printf '%s' "$class" | tr '[:upper:]' '[:lower:]')"
    mkdir -p "$tmp/$tree/definitions" "$tmp/$tree/BMMs" "$tmp/$tree/classes"
    jq -r --arg class "$class" --arg module "$module" \
      --argjson own "$own" --argjson rm "$rm_pages" --argjson base "$base_types" \
      "$render_program" "$bmm" >"$tmp/$tree/definitions/$name.adoc"
    {
      printf '[source,json]\n--------\n'
      jq --indent 2 --arg class "$class" '.class_definitions[$class]' "$bmm"
      printf -- '--------\n'
    } >"$tmp/$tree/BMMs/$name.adoc"
    # shellcheck disable=SC2016 # `partial$` is Antora syntax, not a shell expansion
    printf '=== %s Class\n\n[tabs]\n====\nDefinition::\n+\ninclude::ROOT:partial$definitions/%s.adoc[]\n\nBMM::\n+\ninclude::ROOT:partial$BMMs/%s.adoc[]\n\n====\n' \
      "$class" "$name" "$name" >"$tmp/$tree/classes/$name.adoc"
  done
  for kind in definitions BMMs classes; do
    if [[ "$mode" == check ]]; then
      if ! diff -r "$tmp/$tree/$kind" "$partials/$kind"; then
        echo "stale: $partials/$kind differs from its rendering of $bmm" >&2
        stale=1
      fi
    else
      rm -rf "${partials:?}/$kind"
      mkdir -p "$partials"
      cp -R "$tmp/$tree/$kind" "$partials/$kind"
    fi
  done
done

if [[ "$mode" == check ]]; then
  if [[ "$stale" -ne 0 ]]; then
    echo "run scripts/render/bmm-partials.sh and commit the partials" >&2
    exit 1
  fi
  echo "the draft class partials match their BMM schemas"
fi
